def permutations_with_weights(N, A, B):
    mod = 998244353
    dp = [0] * (N + 1)
    dp[0] = 1  # Base case: one empty hand

    for i in range(1, N + 1):
        for j in range(0, A + 1):
            if j >= 1:
                dp[j] = (dp[j] + 1) % mod
        for j in range(B, 0, -1):
            if i >= j:
                dp[j] = (dp[j] + dp[j - 1]) % mod

    return (dp[A] * dp[B] + dp[B - 1]) % mod

