from collections import defaultdict

def is_balanced(s):
    bal = [0, 0, 0]
    for ch in s:
        if ch == 'a':
            bal[0] += 1
        elif ch == 'b':
            bal[1] += 1
        elif ch == 'c':
            bal[2] += 1
    return abs(bal[0] - bal[1]) <= 1 and abs(bal[1] - bal[2]) <= 1

def count_balanced_strings(length):
    memo = defaultdict(lambda: -1)
    count = recurse(-1, -1, 0, length, memo)
    return count % 51123987

def recurse(last, prev, left, rest, memo):
    key = (last, prev, left, rest)

    if left == rest == 0:
        return 1

    if memo[key] != -1:
        return memo[key]

    res = 0
    current = []
    if left:
        if last == -1 and prev == -1:
            return 0
        if last == 0:
            current.append('a')
        if prev == 0 and last == 0:
            current.append('b')
        if prev == 0 or last == 0:
            current.append('c')
        with_current = recurse(current.index('a'), current.index('b'), current.index('c'), rest, memo)
        res = with_current % 51123987

    no_current = recurse(last, -1, left-1, rest, memo)
    res += no_current 

    memo[key] = res % 51123987
    return memo[key]

