from collections import defaultdict

def balanced_strings(start_string):
    mod = 51123987

    def freq(s):
        return [s.count('a'), s.count('b'), s.count('c')]

    def diff(a, b):
        return abs(a - b) <= 1

    def neighbor_changes(a, b, c):
        if diff(a, b) and diff(b, c) and diff(c, a):
            return True
        if not diff(a, c) and diff(a, b) and diff(b, c):
            return True
        if diff(a, b) and diff(c, b) and diff(b, c):
            return True
        if diff(a, b) and diff(c, b) and diff(b, a):
            return True
        if diff(a, b) and diff(a, c) and diff(b, c):
            return True
        return False

    start_freq = freq(start_string)
    visited = defaultdict(bool)
    bfs_queue = [(0, freq(start_string))]

    visited[0, *start_freq] = True
    bfs_queue.append((0, freq(start_string)))

    ans = 0
    while bfs_queue:
        state_frequency, current_frequency = bfs_queue.pop(0)

        for change in [(-1, 0, 0), (0, -1, 0), (0, 0, -1)]:
            new_state_frequency = tuple(j + change[k] for k, j in enumerate(current_frequency))
            if not visited[new_state_frequency]:
                visited[new_state_frequency] = True
                possible = True
                for k in range(3):
                    possible = neighbor_changes(start_freq[k], current_frequency[k+1], current_frequency[k])
                    if not possible:
                        break
                if possible:
                    bfs_queue.append((state_frequency, current_frequency + change))

        ans = (ans + (state_frequency[start_freq.index(0)] + 1) * 3) % mod

    return ans

