from collections import Counter

def f_index(index, cards):
    shuffled = [
        index + (k - j) % k
        for j, k in enumerate(cards)
    ]
    return Counter(cards[i] - shuffled[i] for i in range(len(cards)))

def f_query(l, r, cards):
    if l:
        f_l1 = f_index(l-1, cards)
        f_l2 = Counter(cards)
        for l in (f_l1.values() | f_l2.values()): yield f_l1 * f_l2[l]
    for index in range(cards.index(l), cards.index(r)+1):
        yield from f_index(index, cards)

def main(n, k, cards):
    return sum(len(set(p)) for p in f_query(1, n+1, cards))

if __name__ == '__main__':
    n, k = map(int, input().split())
    cards = [[int(x) for x in input().split()] for _ in range(n)]
    print(main(n, k, cards))
