def count_palindromic_pairs(S):
    n = len(S)
    dp = [[False] * n for _ in range(n)]
    count = 0

    for i in range(n-1, -1, -1):
        dp[i][i] = True
        count += i + 1  # Starting pair

    for length in range(3, n+1):
        for start in range(n - length + 1):
            end = start + length - 1
            if S[start] == S[end] and (length == 3 or dp[start + 1][end - 1]):
                dp[start][end] = True
                count += length + 1  # Length of palindrome is calculated by the length of palindromes ending and starting from middle points
                if length % 2 == 0:
                    dp[start + length // 2][end - length // 2] = True  # handling cases where length is even

    return count

