def balanced_strings(n, s):
    dp = [[0] * 3 for _ in range(1 << n)]
    valid = set()

    for i in range(n):
        new_s = s[i:] + s[:i]
        freq = [0] * 3
        for j, ch in enumerate(new_s):
            if ch == 'a':
                freq[0] += 1
            elif ch == 'b':
                freq[1] += 1
            elif ch == 'c':
                freq[2] += 1
            freq[j % 3] -= 1
            if freq[j % 3] == 0:
                freq[j % 3] = 1  # If frequency reaches zero, reset to count

        unique_count = sum(freq)
        bitwise = sum(freq[j] for j in range(3)) % 2  # Bitwise XOR (1 or 0)

        if unique_count in [0, 1, 2] and unique_count == bitwise:
            for used_freq in range(3):
                combo = bit_count = 0
                not_valid = set([0, 1, 2])
                for j in range(3):
                    if freq[j] == 0:
                        not_valid.remove(combo)
                    combo += freq[j] // 2
                    if freq[j] // 2 > shift_left:
                        not_valid.remove(combo)
                    combo ^= freq[j]
                    if combo == i:
                        shift_left |= 1 << j
                        break

                dp[used_freq][0] += bit_map[not_valid]
                if not_valid != set():
                    valid.add(shift_left)
                    dp[used_freq][1] += bit_count % mod
                else:
                    dp[used_freq][2] += bit_map[not_valid] % mod

    return dp[0][0]

