def factorial(n, mod=1000000007):
    result = 1
    for i in range(1, n+1):
        result = (result * i) % mod
    return result

def divide_vertices_into_pairs(n):
    if n % 2 != 0:
        return 0

    mod = 1000000007
    m = n // 2
    dp = [1] * (m + 1)
    dp[1] = 2

    for i in range(2, m + 1):
        for j in range(m // 2, 0, -1):
            dp[j] = (dp[j] * j * 2) % mod
        for k in range(1, j):
            dp[j] = (dp[j] - (k * (k + 1)) * (k - 1) * i // 2) % mod

    return (dp[-1] * factorial(m) * factorial(m) * 2) % mod

def count_ways_to_divide(n):
    ways = 0
    for i in range(1, n // 2 + 1):
        if (i * (i - 1) // 2 * (i - 2) // 6) % mod == 0:
            ways = ways + ((i * ((i - 1) * ((i - 2) + 1))) % mod + divide_vertices_into_pairs(n) * ((n // i - 1) // 2) % mod) % mod

    return ways

