MOD = 1000000007

def get_permanent(n, k, matrix):
    # Initialize table for Pascal's triangle
    ppts = [[1 if i == j else 0 for j in range(i + 1)] for i in range(n)]

    # Update table with the matrix values for larger elements
    for i, (xi, yi, wi) in enumerate(matrix):
        for j in range(1, min(n, yi + 1)):
            if i == j:
                ppts[xi][j] = wi
            else:
                ppts[xi][j] = ppts[xi][j - 1] + wi

    # Calculate the permanent modulo MOD by multiplying entries from the end of each row with the column entries in the previous row
    result = 0
    for diagonal in range(n):
        for i in range(n - diagonal):
            total = 1
            for j in range(diagonal + 1):
                if i + j >= n:
                    break
                total = total * (ppts[i + j][i] if ppts[i + j][i] != 0 else 1)
                if j + 1 >= n - diagonal:
                    break
                total = total * (ppts[n - diagonal + 1][i + j] if ppts[n - diagonal + 1][i + j] != 0 else 1)
            result += total
        result %= MOD

    return result
