from collections import defaultdict

def count_palindromic_pairs(s):
    def extend_palindrome(s, left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return (left + 1, right)

    dp = defaultdict(int)
    for i in range(len(s)):
        dp[i, 0] = 1
        for mid in range(1, i + 2):
            if s[i] != s[mid]:
                continue
            if i - mid + 1 > mid:
                new_left, new_right = extend_palindrome(s, i, mid)
                dp[i, mid] = dp[i, mid - 1] + dp[new_left, mid - new_right]
            else:
                dp[i, mid] = dp[i, mid - 1] + 1
    return dp[len(s) - 1, 1]

