            return False
    return True

def update_server_processes(stack, starts):
    for i, attr in enumerate(starts):
        if attr:
            update_processes(i, stack, processes_on_servers[i])

def update_processes(start, stack, processes_on_server):
    next_process = start + 1

    update_capability(next_process - start, stack, processes_on_server, processes_on_server[start], processes_on_server[start + n])

    while stacks_count(stack) <= 4 * next_process - 1:
        stack[-1] ^= 1

    update_stack(stack, starts)

def stacks_count(stack):
    count = 0
    while stack:
        count += 1
        if 1 in stack:
            stack.remove(1)
        else:
            break
    return count

def update_stack(stack, starts):
    earliest_started = stack[-1] ^ 1

    while stack:
        start_two = stack.pop()
        if start_two > earliest_started or 1 in processes_on_servers[start_two]:
            continue

        if starts[start_two]:
            starts[start_two] = 0

        stack.append(start_two ^ 1)

def main():
    if is_valid_distribution(server_processes):
        print("YES")
        print(find_valid_rules())
    else:
        print("NO")

if __name__ == "__main__":
    main()
