from heapq import heappush, heappop

def simulate_game(n, a, k):
    if k == 0:
        return a

    intervals = [k // 2]
    if k % 2 != 0:
        intervals.append(k // 2 + 1)

    max_juiciness = a[n - 1]
    min_juiciness = a[0]

    for i in range(n - 2, 0, -1):
        if intervals[0] <= i <= intervals[1]:
            max_juiciness = max(max_juiciness, a[i])
        if k % 2 == 0:
            min_juiciness = min(min_juiciness, a[i])
        else:
            heappush(intervals, i + 1)
            if k > 1:
                heappop(intervals)

    while intervals:
        max_juiciness = max(max_juiciness, a[heappop(intervals) - 1])

    return max_juiciness, min_juiciness

# Read input
n = int(input().strip())
a = list(map(int, input().strip().split()))

# Calculate results for each k
results = []
for k in range(n):
    results.append(simulate_game(n, a, k))

# Output results
for result in results:
    print(result)
