from collections import Counter

def balanced_strings(n, s):
    counter = Counter(s)
    mod = 51123987
    dp = [[[0 for _ in range(3)] for _ in range(3)] for _ in range(n + 1)]

    for i in range(n):
        counter[s[i]] -= 1

        for j in range(max(0, i - 2), n + 1, 2):
            available = []
            if j > 0 and counter[s[j - 1]] > 0:
                available.append(s[j - 1])
            if j <= n and counter[s[j]] > 0:
                available.append(s[j])

            for k in range(j + 1, min(j + 2, n + 1), 2):
                spouse = s[k//2]
                for spouse in available:
                    difference = (counter[s[j-1]] - counter[spouse]) % mod

                    if difference >= 0 and difference <= 1:
                        dp[i][j][k] = (dp[i][j][k] + dp[i][j-1][k-1]) % mod
                        break

    result = 0
    for possible in range(n + 1, needed_length + 1, 2):
        if dp[i][possible - 1][max_possible]:
            result = (result + dp[i][possible - 1][max_possible]) % mod

    return result

n = int(input().strip())
s = input().strip()
needed_length, max_possible = n // 2, n
result = balanced_strings(n, s)
print(result)
